CREATE TABLE public.courses (id text PRIMARY KEY, title text NOT NULL, description text NOT NULL, category text NOT NULL DEFAULT 'AI foundations', objectives text[] NOT NULL DEFAULT '{}', is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.courses TO anon, authenticated; GRANT ALL ON public.courses TO service_role;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "demo courses readable" ON public.courses FOR SELECT TO anon, authenticated USING (is_demo);
CREATE TRIGGER touch_courses BEFORE UPDATE ON public.courses FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.lessons (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, course_id text REFERENCES public.courses(id) ON DELETE CASCADE, user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, duration_seconds double precision NOT NULL DEFAULT 0 CHECK (duration_seconds >= 0), video_url text NOT NULL, provider text NOT NULL DEFAULT 'direct' CHECK (provider IN ('direct','youtube','vimeo')), transcript jsonb NOT NULL DEFAULT '[]', transcript_status text NOT NULL DEFAULT 'unavailable' CHECK (transcript_status IN ('available','unavailable','failed')), is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((is_demo AND user_id IS NULL AND course_id IS NOT NULL) OR (NOT is_demo AND user_id IS NOT NULL)));
GRANT SELECT ON public.lessons TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.lessons TO authenticated; GRANT ALL ON public.lessons TO service_role;
ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read demo lessons" ON public.lessons FOR SELECT TO anon, authenticated USING (is_demo);
CREATE POLICY "manage own lessons" ON public.lessons FOR ALL TO authenticated USING (auth.uid() = user_id AND NOT is_demo) WITH CHECK (auth.uid() = user_id AND NOT is_demo);
CREATE TRIGGER touch_lessons BEFORE UPDATE ON public.lessons FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.lesson_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE, lesson_id text NOT NULL REFERENCES public.lessons(id) ON DELETE CASCADE, position_seconds double precision NOT NULL DEFAULT 0 CHECK (position_seconds >= 0), watched_seconds double precision NOT NULL DEFAULT 0 CHECK (watched_seconds >= 0), completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, lesson_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lesson_progress TO authenticated; GRANT ALL ON public.lesson_progress TO service_role;
ALTER TABLE public.lesson_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own lesson progress" ON public.lesson_progress FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.lessons l WHERE l.id = lesson_id AND (l.is_demo OR l.user_id = auth.uid()))) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.lessons l WHERE l.id = lesson_id AND (l.is_demo OR l.user_id = auth.uid())));
CREATE TRIGGER touch_lesson_progress BEFORE UPDATE ON public.lesson_progress FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.lesson_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE, lesson_id text NOT NULL REFERENCES public.lessons(id) ON DELETE CASCADE, body text NOT NULL CHECK (length(trim(body)) BETWEEN 1 AND 10000), timestamp_seconds double precision NOT NULL DEFAULT 0 CHECK (timestamp_seconds >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lesson_notes TO authenticated; GRANT ALL ON public.lesson_notes TO service_role;
ALTER TABLE public.lesson_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own lesson notes" ON public.lesson_notes FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.lessons l WHERE l.id = lesson_id AND (l.is_demo OR l.user_id = auth.uid()))) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.lessons l WHERE l.id = lesson_id AND (l.is_demo OR l.user_id = auth.uid())));
CREATE TRIGGER touch_lesson_notes BEFORE UPDATE ON public.lesson_notes FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.lesson_bookmarks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE, lesson_id text NOT NULL REFERENCES public.lessons(id) ON DELETE CASCADE, label text NOT NULL DEFAULT 'Saved moment' CHECK (length(label) BETWEEN 1 AND 200), timestamp_seconds double precision NOT NULL CHECK (timestamp_seconds >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lesson_bookmarks TO authenticated; GRANT ALL ON public.lesson_bookmarks TO service_role;
ALTER TABLE public.lesson_bookmarks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own lesson bookmarks" ON public.lesson_bookmarks FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.lessons l WHERE l.id = lesson_id AND (l.is_demo OR l.user_id = auth.uid()))) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.lessons l WHERE l.id = lesson_id AND (l.is_demo OR l.user_id = auth.uid())));
CREATE TRIGGER touch_lesson_bookmarks BEFORE UPDATE ON public.lesson_bookmarks FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE INDEX lessons_course ON public.lessons(course_id, position); CREATE INDEX lessons_owner ON public.lessons(user_id); CREATE INDEX lesson_notes_owner ON public.lesson_notes(user_id, lesson_id); CREATE INDEX lesson_bookmarks_owner ON public.lesson_bookmarks(user_id, lesson_id);
INSERT INTO public.courses(id,title,description,category,objectives,is_demo) VALUES ('understanding-rag','Understanding RAG: From Retrieval to Grounded Answers','Explore embeddings, semantic and hybrid search, knowledge graphs, and the evidence behind a grounded answer. Three original short lessons with synthetic narration and matching study resources.','AI foundations',ARRAY['Explain embeddings and cosine similarity','Compare keyword and semantic search','Understand reciprocal rank fusion','Connect knowledge graphs with source evidence','Evaluate citations and recognize unsupported claims'],true);
INSERT INTO public.lessons(id,course_id,title,description,position,duration_seconds,video_url,transcript_status,is_demo,transcript) VALUES
('embeddings','understanding-rag','Meaning in numbers','Embeddings, cosine similarity, and why relevance is not certainty.',1,56.2,'/__l5e/assets-v1/432b27e5-9047-4de3-837d-9b05ac01992d/embeddings.mp4','available',true,'[{"start":0,"end":15.76,"heading":"What is an embedding?","text":"An embedding is a list of numbers that represents a piece of content. A trained model maps related meanings to nearby positions in a vector space. The numbers are not hand-written labels, and their meaning depends on the model."},{"start":15.76,"end":36.72,"heading":"Similarity, not certainty","text":"Imagine the phrases car repair and fixing an automobile. Their words differ, but their meanings are related. Embeddings can place them near each other. Cosine similarity measures how closely two vectors point in the same direction. It is a similarity score, not a probability of correctness."},{"start":36.72,"end":56.2,"heading":"A consistent vector space","text":"Encode the query and the documents with the same compatible embedding model. Compare their vectors and rank candidate passages. An embedding does not verify a fact. It helps find material that might be useful, and the retrieved text still needs inspection."}]'),
('hybrid-search','understanding-rag','Finding the right evidence','Combine keyword precision with semantic meaning, while respecting permissions.',2,60.2,'/__l5e/assets-v1/placeholder/hybrid-search.mp4','available',true,'[{"start":0,"end":20.32,"heading":"Two ways to search","text":"Keyword search rewards exact terms. Semantic search uses embeddings to match related meanings. An error code such as E forty two benefits from exact matching, while a paraphrased question may benefit from semantic matching. Neither method is best for every query."},{"start":20.32,"end":40.6,"heading":"Combine ranked results","text":"Hybrid retrieval combines keyword and vector search. Reciprocal rank fusion is one way to merge results. For each result, add one divided by a constant plus its rank in each list. This uses rank rather than pretending that different search scores share the same scale."},{"start":40.6,"end":60.2,"heading":"Permissions come first","text":"Search only sources the learner is allowed to read. For a video question at the current position, exclude future transcript segments before ranking evidence. Preserve the source title and timestamp with each passage. Good relevance never overrides ownership or scope."}]'),
('grounded-answers','understanding-rag','From retrieval to grounded answers','Knowledge graphs, supporting citations, and honest uncertainty.',3,61.12,'/__l5e/assets-v1/placeholder/grounded-answers.mp4','available',true,'[{"start":0,"end":19.32,"heading":"Evidence before answers","text":"Retrieval augmented generation supplies selected source passages to a language model. The model can then draft an answer with references to those passages. A knowledge graph can connect concepts and resources, but a graph edge is not automatically proof that a claim is true."},{"start":19.32,"end":38.92,"heading":"Citations must support claims","text":"A useful citation identifies a source and its location, such as a video timestamp or a PDF page. Check that the cited passage actually supports the claim. Adding a citation label does not make an answer grounded, and retrieval does not eliminate hallucinations."},{"start":38.92,"end":61.12,"heading":"Know when to abstain","text":"If the permitted evidence is missing or contradictory, say that there is not enough support. Distinguish source-supported facts from general explanation. Grounded systems reduce risk through permission checks, scoped retrieval, source inspection, and honest uncertainty, not through a promise of perfect accuracy."}]');